{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Linezolid absolute oral bioavailability was 100% in patients when oral dosing was compared with intravenous administration, directly supporting F ≥ 20%."
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib absolute oral bioavailability was 97.2% (90% CI 86–110) in healthy subjects after a 400 mg oral solution versus intravenous infusion, directly supporting F ≥ 20%."
    },
    {
      "card_ids": ["C04"],
      "claim": "Tazemetostat mean absolute oral bioavailability was 33.9% in patients after 800 mg tablets versus intravenous bolus, still above the 20% threshold and supporting high bioavailability."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": [],
  "decision_summary": "All numeric human absolute-bioavailability evidence transfers positively, with F values from about 32% to 100%, all above the 20% threshold. The main uncertainty is the absence of direct modified-release formulation data, so confidence is moderate rather than high.",
  "evidence_gaps": [
    "No direct modified-release formulation bioavailability record is supplied; the evidence is from conventional oral formulations.",
    "One qualitative record (C08) reports only 'good bioavailability' without a numeric F value and is not threshold-relevant."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C01", "C02", "C04"],
  "revision_action": "initial",
  "supportive_card_ids": ["C01", "C02", "C04"]
}

